int heap[N], sz;

void up(int i) {
    while (i > 1 && heap[i] > heap[i/2]) {
        swap(heap[i], heap[i/2]);
        i /= 2;
    }
}

void down(int i) {
    while (2*i <= sz) {
        int j = 2*i;
        if (j+1 <= sz && heap[j+1] > heap[j]) j++;
        if (heap[i] >= heap[j]) break;
        swap(heap[i], heap[j]);
        i = j;
    }
}

void push(int x) { heap[++sz] = x; up(sz); }
void pop() { heap[1] = heap[sz--]; down(1); }
